/**
 * Update Subgraph Addresses Script
 *
 * This script updates subgraph.yaml with deployed contract addresses
 * from the deployment JSON generated by Foundry scripts.
 *
 * Usage:
 *   node scripts/update-addresses.js [path-to-deployment-json]
 */

const fs = require('fs');
const path = require('path');

// Default deployment JSON path
const DEFAULT_DEPLOYMENT_PATH = '../contracts/broadcast/Deploy.s.sol/84532/run-latest.json';

function loadDeploymentData(deploymentPath) {
  const fullPath = path.join(__dirname, deploymentPath);

  if (!fs.existsSync(fullPath)) {
    console.error(`Error: Deployment file not found at ${fullPath}`);
    console.error('Please deploy contracts first using: cd contracts && forge script script/Deploy.s.sol --broadcast');
    process.exit(1);
  }

  const data = JSON.parse(fs.readFileSync(fullPath, 'utf8'));
  return data;
}

function extractContractAddresses(deploymentData) {
  const addresses = {};

  // Parse Foundry broadcast JSON to extract deployed contract addresses
  if (deploymentData.transactions) {
    for (const tx of deploymentData.transactions) {
      if (tx.transactionType === 'CREATE' && tx.contractName) {
        addresses[tx.contractName] = tx.contractAddress;
      }
    }
  }

  return addresses;
}

function updateSubgraphYaml(addresses, startBlock) {
  const subgraphPath = path.join(__dirname, '../subgraph.yaml');

  if (!fs.existsSync(subgraphPath)) {
    console.error(`Error: subgraph.yaml not found at ${subgraphPath}`);
    process.exit(1);
  }

  let content = fs.readFileSync(subgraphPath, 'utf8');

  // Update PositionVault address and start block
  if (addresses.PositionVault) {
    content = content.replace(
      /name: PositionVault[\s\S]*?address: "0x[a-fA-F0-9]{40}"/,
      `name: PositionVault\n    network: base-sepolia\n    source:\n      address: "${addresses.PositionVault}"`
    );
    content = content.replace(
      /(name: PositionVault[\s\S]*?startBlock: )\d+/,
      `$1${startBlock}`
    );
  }

  // Update Protector address and start block
  if (addresses.Protector) {
    content = content.replace(
      /name: Protector[\s\S]*?address: "0x[a-fA-F0-9]{40}"/,
      `name: Protector\n    network: base-sepolia\n    source:\n      address: "${addresses.Protector}"`
    );
    content = content.replace(
      /(name: Protector[\s\S]*?startBlock: )\d+/,
      `$1${startBlock}`
    );
  }

  // Update DemoEscrow address and start block
  if (addresses.DemoEscrow) {
    content = content.replace(
      /name: DemoEscrow[\s\S]*?address: "0x[a-fA-F0-9]{40}"/,
      `name: DemoEscrow\n    network: base-sepolia\n    source:\n      address: "${addresses.DemoEscrow}"`
    );
    content = content.replace(
      /(name: DemoEscrow[\s\S]*?startBlock: )\d+/,
      `$1${startBlock}`
    );
  }

  fs.writeFileSync(subgraphPath, content, 'utf8');
  console.log('✅ Updated subgraph.yaml with contract addresses');
}

function updateEnvFile(addresses, startBlock) {
  const envPath = path.join(__dirname, '../.env');
  const envExamplePath = path.join(__dirname, '../.env.example');

  // Create .env from .env.example if it doesn't exist
  if (!fs.existsSync(envPath) && fs.existsSync(envExamplePath)) {
    fs.copyFileSync(envExamplePath, envPath);
    console.log('✅ Created .env file from .env.example');
  }

  if (!fs.existsSync(envPath)) {
    console.warn('⚠️  Warning: .env file not found');
    return;
  }

  let content = fs.readFileSync(envPath, 'utf8');

  // Update addresses
  if (addresses.PositionVault) {
    content = content.replace(
      /POSITION_VAULT_ADDRESS=0x[a-fA-F0-9]{40}/,
      `POSITION_VAULT_ADDRESS=${addresses.PositionVault}`
    );
  }
  if (addresses.Protector) {
    content = content.replace(
      /PROTECTOR_ADDRESS=0x[a-fA-F0-9]{40}/,
      `PROTECTOR_ADDRESS=${addresses.Protector}`
    );
  }
  if (addresses.DemoEscrow) {
    content = content.replace(
      /DEMO_ESCROW_ADDRESS=0x[a-fA-F0-9]{40}/,
      `DEMO_ESCROW_ADDRESS=${addresses.DemoEscrow}`
    );
  }

  // Update start blocks
  content = content.replace(
    /POSITION_VAULT_START_BLOCK=\d+/,
    `POSITION_VAULT_START_BLOCK=${startBlock}`
  );
  content = content.replace(
    /PROTECTOR_START_BLOCK=\d+/,
    `PROTECTOR_START_BLOCK=${startBlock}`
  );
  content = content.replace(
    /DEMO_ESCROW_START_BLOCK=\d+/,
    `DEMO_ESCROW_START_BLOCK=${startBlock}`
  );

  fs.writeFileSync(envPath, content, 'utf8');
  console.log('✅ Updated .env file with contract addresses');
}

function main() {
  const args = process.argv.slice(2);
  const deploymentPath = args[0] || DEFAULT_DEPLOYMENT_PATH;

  console.log('🔄 Loading deployment data...');
  const deploymentData = loadDeploymentData(deploymentPath);

  console.log('📝 Extracting contract addresses...');
  const addresses = extractContractAddresses(deploymentData);

  // Get start block from deployment (use first transaction block)
  const startBlock = deploymentData.transactions?.[0]?.transaction?.blockNumber || 0;

  console.log('\nFound contracts:');
  console.log(`  PositionVault: ${addresses.PositionVault || 'NOT FOUND'}`);
  console.log(`  Protector: ${addresses.Protector || 'NOT FOUND'}`);
  console.log(`  DemoEscrow: ${addresses.DemoEscrow || 'NOT FOUND'}`);
  console.log(`  Start Block: ${startBlock}`);

  if (!addresses.PositionVault || !addresses.Protector || !addresses.DemoEscrow) {
    console.error('\n❌ Error: Not all required contracts found in deployment data');
    process.exit(1);
  }

  console.log('\n🔄 Updating configuration files...');
  updateSubgraphYaml(addresses, startBlock);
  updateEnvFile(addresses, startBlock);

  console.log('\n✅ Configuration updated successfully!');
  console.log('\nNext steps:');
  console.log('  1. Run: npm run prepare-abis');
  console.log('  2. Run: npm run codegen');
  console.log('  3. Run: npm run build');
  console.log('  4. Run: npm run deploy-local (or npm run deploy for hosted service)');
}

main();
